        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var composite = last.results ? last.results.compositeScore : 0;

            var performance = window.mySimulation.t('perf_poor');
            if (composite >= 90) performance = window.mySimulation.t('perf_leadership');
            else if (composite >= 75) performance = window.mySimulation.t('perf_advanced');
            else if (composite >= 60) performance = window.mySimulation.t('perf_proficient');
            else if (composite >= 40) performance = window.mySimulation.t('perf_developing');

            var insights = [];
            var lastResults = last.results || {};
            if (lastResults.circularityRate > 55) insights.push(window.mySimulation.t('insight_strong_circularity'));
            if (lastResults.circularityRate <= 30) insights.push(window.mySimulation.t('insight_low_circularity'));
            if (lastResults.costPerUnit < 175) insights.push(window.mySimulation.t('insight_cost_optimized'));
            if (lastResults.costPerUnit > 195) insights.push(window.mySimulation.t('insight_cost_increased'));
            if (lastResults.satisfaction > 60) insights.push(window.mySimulation.t('insight_csat_improved'));
            if (lastResults.envScore > 60) insights.push(window.mySimulation.t('insight_env_progress'));

            return {
                compositeScore: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            if (ds.capital < 10000000 && state.currentPeriod < 5)
                return window.mySimulation.t('hint_low_capital');
            if (results.compositeScore < 30)
                return window.mySimulation.t('hint_low_score');
            if (ds.circularityRate < 20 && state.currentPeriod > 2)
                return window.mySimulation.t('hint_low_circularity');
            if (results.compositeScore > 70)
                return window.mySimulation.t('hint_strong');
            return null;
        }

